INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2019-10-20 06:49:29', '2019-10-20 05:49:29', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing! asa</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'publish', 'open', 'open', '', 'hello-world', '', '', '2021-11-09 14:10:07', '2021-11-09 16:10:07', '', 0, 'http://localhost:8080/portfolio/wordpress/?p=1', 0, 'post', '', 1),
(7, 1, '2019-10-19 06:57:29', '2019-10-19 05:57:29', 'Hi,\n<h2>I\'m Jadson Santos</h2>\n<h1>Front End Developer</h1>\n<small>Talking with UX Designers, Back End Developers and Users.</small>', 'Home', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2025-03-12 13:01:32', '2025-03-12 16:01:32', '', 0, 'http://localhost:8080/portfolio/wordpress/?page_id=7', 0, 'page', '', 0),
(9, 1, '2019-10-19 07:02:32', '2019-10-19 06:02:32', 'Front End developer with over 15 years of professional experience, based in Aracaju/SE. Vasco\'s fan, from Bahia and brazilian from heart.\n\nI was born and raised in Itabuna, a city in Bahia. When I were a child, I always dreamed of becoming an civil engineer, though I occasionally considered becoming a veterinarian. My mother wished for me to pursue a career in nursing, and over time, I thought about study in economics, management, or mathematics. However, my passion alwayes computer science, which I ultimately chose to study at university.\n\nIn April 2010, I graduated in Information Systems and moved to Rio de Janeiro, where I worked as a Front End Developer at ZONAInternet agency until November 2012.\n\nFrom December 2012 to October 2020, I had a great experience working as a Front End Developer at CENPES/Petrobras. After that, from November 2020 to March 2025, I thoroughly enjoyed working remotely as a developer at LAMCSO/COPPE/UFRJ.\n\nCurrently, I live in Aracaju, SE, and my new goals are focused on working remotely as a developer with the LCCV/UFAL development team.', 'About Me', '', 'publish', 'closed', 'closed', '', 'about', '', '', '2025-03-18 16:29:26', '2025-03-18 19:29:26', '', 0, 'http://localhost:8080/portfolio/wordpress/?page_id=9', 0, 'page', '', 0),
(11, 1, '2019-10-20 07:03:25', '2019-10-20 06:03:25', '', 'Works', '', 'publish', 'closed', 'closed', '', 'works', '', '', '2019-10-20 07:03:25', '2019-10-20 06:03:25', '', 0, 'http://localhost:8080/portfolio/wordpress/?page_id=11', 0, 'page', '', 0),
(15, 1, '2019-10-20 07:07:48', '2019-10-20 06:07:48', '', 'Contact', '', 'publish', 'closed', 'closed', '', 'contact', '', '', '2019-10-20 07:07:48', '2019-10-20 06:07:48', '', 0, 'http://localhost:8080/portfolio/wordpress/?page_id=15', 0, 'page', '', 0),
(34, 1, '2004-06-01 08:00:42', '2004-06-01 07:00:42', '', 'Started on Information System graduated course at \'Faculdade de Tecnologia e Ciências - FTC/Itabuna-Ba\'.', 'Started on Information System graduated course at \'Faculdade de Tecnologia e Ciências - FTC/Itabuna-Ba\'.', 'publish', 'closed', 'closed', '', '34-2', '', '', '2019-10-28 04:48:50', '2019-10-28 04:48:50', '', 0, 'http://localhost:8080/portfolio/wordpress/?post_type=timeline&#038;p=34', 0, 'timeline', '', 0),
(35, 1, '2005-11-01 08:00:13', '2005-11-01 10:00:13', '', 'Co-founder of the website NaZoera, a platform for registering events in the city of Itabuna. Over 10 years of experience working as an IT manager.', '', 'publish', 'closed', 'closed', '', 'auto-draft', '', '', '2025-11-27 10:06:58', '2025-11-27 13:06:58', '', 0, 'http://localhost:8080/portfolio/wordpress/?post_type=timeline&#038;p=35', 0, 'timeline', '', 0),
