(7433, 1778757979, 1778757979, 'new', 'wfUpgrade', 25, 'bc5633b4ef51507eb64b3ddd16bf9e98', 'bc5633b4ef51507eb64b3ddd16bf9e98', 'Your WordPress version is out of date', 'WordPress version 6.9.4 is now available. Please upgrade immediately to get the latest fixes and compatibility updates from WordPress. <a href=\"https://www.wordfence.com/help/?query=scan-result-core-upgrade\" target=\"_blank\" rel=\"noopener noreferrer\">Learn more<span class=\"screen-reader-text\"> (opens in new tab)</span></a>', 'a:2:{s:14:\"currentVersion\";s:5:\"6.5.8\";s:10:\"newVersion\";s:5:\"6.9.4\";}'),
(7435, 1778757979, 1778757979, 'new', 'wfPluginAbandoned', 50, 'cdb758d0cd50d625abee997a22dc5fab', 'cdb758d0cd50d625abee997a22dc5fab', 'The Plugin \"Multiple Post Thumbnails\" appears to be abandoned (updated 26th November 2018, tested to WP 5.0.25).', 'It was last updated 7 years 5 months ago and tested up to WordPress 5.0.25. It may have compatibility problems with the current version of WordPress or unknown security issues. <a href=\"https://www.wordfence.com/help/?query=scan-result-plugin-abandoned\" target=\"_blank\" rel=\"noopener noreferrer\">Get more information.<span class=\"screen-reader-text\"> (opens in new tab)</span></a>', 'a:25:{s:4:\"name\";s:24:\"Multiple Post Thumbnails\";s:4:\"slug\";s:24:\"multiple-post-thumbnails\";s:7:\"version\";s:3:\"1.7\";s:6:\"author\";s:68:\"<a href=\"https://profiles.wordpress.org/chrisscott/\">Chris Scott</a>\";s:14:\"author_profile\";s:42:\"https://profiles.wordpress.org/chrisscott/\";s:8:\"requires\";s:5:\"2.9.2\";s:6:\"tested\";s:6:\"5.0.25\";s:12:\"requires_php\";s:3:\"5.6\";s:16:\"requires_plugins\";a:0:{}s:13:\"compatibility\";a:0:{}s:11:\"num_ratings\";i:42;s:11:\"support_url\";s:62:\"https://wordpress.org/support/plugin/multiple-post-thumbnails/\";s:15:\"support_threads\";i:0;s:24:\"support_threads_resolved\";i:0;s:12:\"last_updated\";s:21:\"2018-11-26 6:32pm GMT\";s:8:\"homepage\";s:61:\"http://wordpress.org/extend/plugins/multiple-post-thumbnails/\";s:14:\"upgrade_notice\";a:1:{s:3:\"0.6\";s:197:\"<p>get_the_post_thumbnail return filter changed to use the format <code>{$post_type}_{$thumb_id}_thumbnail_html</code> which allows filtering by post type and thumbnail id which was the intent.</p>\";}s:14:\"business_model\";b:0;s:14:\"repository_url\";s:0:\"\";s:22:\"commercial_support_url\";s:0:\"\";s:12:\"preview_link\";s:0:\"\";s:11:\"dateUpdated\";s:18:\"26th November 2018\";s:9:\"abandoned\";b:1;s:10:\"vulnerable\";b:0;s:5:\"wpURL\";s:54:\"https://wordpress.org/plugins/multiple-post-thumbnails\";}');
